fn sqlite_snapshot_semio_drawing_explicit_controlled_native_owner(){use store::{pack::snapshot::ArtifactPack,pack::snapshot::ArtifactDsl};let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let expected=fixture();for payload in [store::io::IoPayload::Binary(expected.encode_pack()),store::io::IoPayload::Text(expected.print_dsl())]{let actual=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap();assert_eq!(actual,expected);assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()), native_owner)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["nativeAdmission"]["tinyBudgetBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()}), native_owner)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()}), native_owner)).is_err());}let count=f["nativeAdmission"]["collectionItems"].as_u64().unwrap() as usize;let canceled=f["nativeAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let value=SemioDrawingSnapshot{schema:expected.schema,layers:vec![DrawLayer{id:"layer".into(),name:"".into(),visible:true,root:DrawNode::Group{transform:SemioTransform::identity(),children:(0..count).map(|_|DrawNode::Text{value:"".into(),at:SemioPoint2{x:-0.0,y:0.0},style:None}).collect()}}],..SemioDrawingSnapshot::default()};for payload in [store::io::IoPayload::Binary(value.encode_pack()),store::io::IoPayload::Text(value.print_dsl())]{let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==count&&p.completed==canceled{interior=true;false}else{true}};assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default()), native_owner)).is_err());assert!(interior);}let mut root=DrawNode::default();for _ in 0..f["nativeAdmission"]["maximumDepth"].as_u64().unwrap()+1{root=DrawNode::Group{transform:SemioTransform::identity(),children:vec![root]};}let deep=SemioDrawingSnapshot{layers:vec![DrawLayer{id:"deep".into(),root,..DrawLayer::default()}],..SemioDrawingSnapshot::default()};assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioDrawingSnapshot::decode_sqlite_snapshot_native(&store::io::IoPayload::Binary(deep.encode_pack()),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).is_err());}

